window.MOTIF_CATALOG_CHUNKS[9]={"cards":[{"id":"ML-T00939","row_version":2,"title":"냉정한 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00938","tag_path":[],"summary":"냉정한 인물은 위기나 감정적 자극에도 감정을 크게 드러내지 않고 차분한 판단을 유지하는 경향이 있다. 침착함이 잔인함이나 무관심을 뜻한다고 단정하지 말고, 타인의 감정을 느끼면서도 표현을 억제하는 경우와 구별한다.","accent":"#7B7594","tab":"#A07A87","facet":"인물","bookmark":"냉정한 인물","entry_url":"cards/ML-T00939/index.html"},{"id":"ML-T00940","row_version":2,"title":"다정한 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00938","tag_path":[],"summary":"다정한 인물은 타인의 필요와 감정을 살피고 배려나 애정을 행동으로 표현하는 경향이 있다. 친절한 말투 한 번보다 지속적인 돌봄과 존중을 기준으로 보며, 호의가 반드시 순진함이나 무조건적인 동의를 뜻하지는 않는다.","accent":"#7B7594","tab":"#A07A87","facet":"인물","bookmark":"다정한 인물","entry_url":"cards/ML-T00940/index.html"},{"id":"ML-T00941","row_version":2,"title":"충동적 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00938","tag_path":[],"summary":"충동적 인물은 결과를 충분히 따져보기 전에 순간의 감정이나 욕구에 따라 행동하는 경향이 있다. 대담하거나 빠르게 결단하는 것만으로 판단하지 말고, 숙고를 건너뛰는 선택이 반복되는지 확인한다.","accent":"#7B7594","tab":"#A07A87","facet":"인물","bookmark":"충동적 인물","entry_url":"cards/ML-T00941/index.html"},{"id":"ML-T00942","row_version":2,"title":"완벽주의자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00938","tag_path":[],"summary":"완벽주의자는 결과물이나 수행이 높은 기준에 미치지 못하면 만족하기 어려워 세부를 거듭 점검하거나 수정하는 인물이다. 단순히 유능하거나 꼼꼼한 것과 구별해, 완벽을 향한 기준이 행동과 관계에 실질적인 영향을 주는지 본다.","accent":"#7B7594","tab":"#A07A87","facet":"인물","bookmark":"완벽주의자","entry_url":"cards/ML-T00942/index.html"},{"id":"ML-T00943","row_version":2,"title":"냉소주의자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00938","tag_path":[],"summary":"냉소주의자는 사람의 동기나 사회적 이상을 선의보다 이기심과 위선으로 해석하는 경향이 강한 인물이다. 재치 있는 비판이나 현실적인 의심만으로 분류하지 말고, 불신과 비관이 반복적인 관점으로 작동하는지 살핀다.","accent":"#7B7594","tab":"#A07A87","facet":"인물","bookmark":"냉소주의자","entry_url":"cards/ML-T00943/index.html"},{"id":"ML-T00944","row_version":2,"title":"낙천주의자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00938","tag_path":[],"summary":"낙천주의자는 어려운 상황에서도 좋은 결과의 가능성을 기대하고 긍정적인 면을 찾으려는 인물이다. 순간적인 기분이나 근거 없는 확신과 구별해, 낙관이 역경을 해석하고 행동을 선택하는 지속적인 태도인지 본다.","accent":"#7B7594","tab":"#A07A87","facet":"인물","bookmark":"낙천주의자","entry_url":"cards/ML-T00944/index.html"},{"id":"ML-T00945","row_version":2,"title":"겁쟁이","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00938","tag_path":[],"summary":"겁쟁이는 위험이나 고통을 크게 두려워해 맞서기보다 피하거나 물러서는 경향이 있는 인물이다. 공포를 느끼는 모든 인물을 뜻하지 않으며, 두려움이 반복적으로 행동을 좌우하는지와 용기를 내는 순간이 있는지도 함께 본다.","accent":"#7B7594","tab":"#A07A87","facet":"인물","bookmark":"겁쟁이","entry_url":"cards/ML-T00945/index.html"},{"id":"ML-T00946","row_version":2,"title":"허세꾼","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00938","tag_path":[],"summary":"허세꾼은 실제 능력이나 지위보다 자신을 더 대단하게 보이도록 과장하고 과시하는 인물이다. 자신감이나 정당한 자기 홍보와 구별해, 말과 행동 사이에 과장이나 꾸밈이 드러나는지를 기준으로 삼는다.","accent":"#7B7594","tab":"#A07A87","facet":"인물","bookmark":"허세꾼","entry_url":"cards/ML-T00946/index.html"},{"id":"ML-T00947","row_version":2,"title":"고집쟁이","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00938","tag_path":[],"summary":"고집쟁이는 반대 근거나 상황 변화가 있어도 자신의 생각이나 결정을 쉽게 바꾸지 않는 인물이다. 신념을 지키는 것만으로 보지 말고, 타당한 이유를 듣고도 입장을 재검토하지 않는 경향이 인물의 선택에 나타나는지 살핀다.","accent":"#7B7594","tab":"#A07A87","facet":"인물","bookmark":"고집쟁이","entry_url":"cards/ML-T00947/index.html"},{"id":"ML-T00948","row_version":3,"title":"정체성 장치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"group","parent_id":"ML-F09","tag_path":[],"summary":"정체성 장치는 인물이 누구인지, 타인에게 누구로 알려져 있는지, 스스로를 어떻게 이해하는지를 이야기의 긴장이나 전개에 활용하는 구성 방식이다. 외형 변화나 단순한 신상 정보 공개와 구별해, 정체성에 대한 인식이나 사회적 인정의 차이가 사건에 영향을 주는지 본다.","accent":"#7B7594","tab":"#79866C","facet":"인물","bookmark":"정체성 장치","entry_url":"cards/ML-T00948/index.html"},{"id":"ML-T00949","row_version":4,"title":"이중 정체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00948","tag_path":[],"summary":"이중 정체는 한 인물이 서로 다른 두 정체성을 지니고 각 정체에 따라 별개의 이름·역할·삶을 이어가는 상태다. 비밀 신분처럼 한 정체를 감추는 경우와 겹칠 수 있지만, 두 정체가 모두 인물의 생활이나 서사에서 독립적으로 기능하는지 살핀다.","accent":"#7B7594","tab":"#79866C","facet":"인물","bookmark":"이중 정체","entry_url":"cards/ML-T00949/index.html"},{"id":"ML-T00950","row_version":2,"title":"비밀 신분","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00948","tag_path":[],"summary":"비밀 신분은 인물이 자신의 진짜 이름·소속·역할을 특정 사람들에게 숨기고 다른 신분으로 행동하는 설정이다. 단순한 사생활 보호나 일회성 거짓말과 구별해, 신분 은폐가 인물의 관계나 임무에 지속적인 영향을 주는지 본다.","accent":"#7B7594","tab":"#79866C","facet":"인물","bookmark":"비밀 신분","entry_url":"cards/ML-T00950/index.html"},{"id":"ML-T00951","row_version":1,"title":"출생의 비밀","original":"Secret Birth","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00948","tag_path":[],"summary":"출생과 혈연에 관한 정보가 감춰져 인물의 정체성이나 관계에 영향을 주는 장치다. 비밀의 공개가 기존의 소속과 권력 관계를 바꿀 수 있다.","accent":"#7B7594","tab":"#79866C","facet":"인물","bookmark":"출생의 비밀","entry_url":"cards/ML-T00951/index.html"},{"id":"ML-T00952","row_version":3,"title":"기억을 잃은 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00948","tag_path":[],"summary":"기억을 잃은 인물은 과거의 일부 또는 전부를 기억하지 못해 자신의 경험과 관계를 온전히 알 수 없는 인물이다. 건망증이나 정보를 모르는 상태와 구별해, 기억의 상실이 정체성·선택·사건의 이해에 실제 제약을 주는지 살핀다.","accent":"#7B7594","tab":"#79866C","facet":"인물","bookmark":"기억을 잃은 인물","entry_url":"cards/ML-T00952/index.html"},{"id":"ML-T00953","row_version":2,"title":"가짜 후계자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00948","tag_path":[],"summary":"가짜 후계자는 혈통이나 자격이 있는 후계자가 아닌데도 그 자리를 차지하거나 그럴듯하게 주장하는 인물이다. 단순한 사칭과 구별해, 계승 대상과 정당성의 기준이 분명하고 그 자격의 진위가 갈등에 연결되는지 본다.","accent":"#7B7594","tab":"#79866C","facet":"인물","bookmark":"가짜 후계자","entry_url":"cards/ML-T00953/index.html"},{"id":"ML-T00954","row_version":2,"title":"대역 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00948","tag_path":[],"summary":"대역 인물은 외모나 역할이 다른 사람과 비슷해 그 사람 대신 나타나거나 임무를 수행하는 인물이다. 신분을 완전히 빼앗는 사칭과 구별해, 특정 상황에서 대체자로 쓰이는지와 주변 인물이 누구로 오인하는지를 기준으로 삼는다.","accent":"#7B7594","tab":"#79866C","facet":"인물","bookmark":"대역 인물","entry_url":"cards/ML-T00954/index.html"},{"id":"ML-T00955","row_version":4,"title":"자신을 모르는 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00948","tag_path":[],"summary":"자신을 모르는 인물은 자신의 출신·능력·과거·정체성 가운데 중요한 사실을 알지 못한 채 살아가는 인물이다. 단순한 기억상실에 한정하지 말고, 정보가 감춰졌거나 잘못 전달된 경우도 포함하되 자기 이해의 공백이 서사에 작용하는지 확인한다.","accent":"#7B7594","tab":"#79866C","facet":"인물","bookmark":"자신을 모르는 인물","entry_url":"cards/ML-T00955/index.html"},{"id":"ML-T00956","row_version":3,"title":"외형·표현","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"group","parent_id":"ML-F09","tag_path":[],"summary":"외형·표현은 인물의 생김새와 의복, 몸짓, 장식처럼 시각적으로 드러나는 특징과 그것이 전달하는 인상을 가리킨다. 외모를 성격이나 정체성의 확정적 증거로 취급하지 말고, 작품이 실제로 부여한 기능과 관객이 읽을 수 있는 단서를 구분한다.","accent":"#7B7594","tab":"#AF8665","facet":"인물","bookmark":"외형·표현","entry_url":"cards/ML-T00956/index.html"},{"id":"ML-T00957","row_version":3,"title":"가면 쓴 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00956","tag_path":[],"summary":"가면 쓴 인물은 얼굴을 가리는 물건을 착용해 외모를 숨기거나 특정한 인상을 만들어 내는 인물이다. 변장이나 비밀 신분과 겹칠 수 있지만, 얼굴을 가리는 가면 자체가 표현·기능·상징으로 제시되는지 살핀다.","accent":"#7B7594","tab":"#AF8665","facet":"인물","bookmark":"가면 쓴 인물","entry_url":"cards/ML-T00957/index.html"},{"id":"ML-T00958","row_version":2,"title":"제복 입은 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00956","tag_path":[],"summary":"제복 입은 인물은 소속이나 직무를 나타내는 규격화된 복장을 입어 조직의 일원 또는 특정 역할로 보이는 인물이다. 비슷한 색의 평상복이나 장식용 의상과 구별해, 복장이 소속·권한·직무를 알아보게 하는 기능을 하는지 본다.","accent":"#7B7594","tab":"#AF8665","facet":"인물","bookmark":"제복 입은 인물","entry_url":"cards/ML-T00958/index.html"},{"id":"ML-T00959","row_version":2,"title":"상처를 지닌 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00956","tag_path":[],"summary":"상처를 지닌 인물은 몸에 남은 흉터나 손상이 외형의 특징으로 지속해서 제시되는 인물이다. 일시적인 상처와 구별해 흔적이 남거나 반복적으로 의미 있게 드러나는지 보며, 작품이 제시하지 않은 과거 원인을 임의로 덧붙이지 않는다.","accent":"#7B7594","tab":"#AF8665","facet":"인물","bookmark":"상처를 지닌 인물","entry_url":"cards/ML-T00959/index.html"},{"id":"ML-T00960","row_version":2,"title":"외모와 성격의 대비","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00956","tag_path":[],"summary":"외모와 성격의 대비는 인물의 겉모습이 불러일으키는 예상과 실제 성격이나 행동 사이의 차이를 활용하는 방식이다. 단순히 매력적인 외모와 좋은 성격이 함께 있는 경우는 제외하고, 외형에 따른 기대가 실제 인물상과 어긋나는지 살핀다.","accent":"#7B7594","tab":"#AF8665","facet":"인물","bookmark":"외모와 성격의 대비","entry_url":"cards/ML-T00960/index.html"},{"id":"ML-T00961","row_version":2,"title":"나이와 외형의 불일치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00956","tag_path":[],"summary":"나이와 외형의 불일치는 인물의 실제 나이와 겉으로 보이는 나이가 서로 다르게 제시되는 특징이다. 단순히 젊거나 늙어 보인다는 인상과 구별해, 작품 안에서 두 나이 정보가 함께 확인되며 차이가 인물 이해에 쓰이는지 본다.","accent":"#7B7594","tab":"#AF8665","facet":"인물","bookmark":"나이와 외형의 불일치","entry_url":"cards/ML-T00961/index.html"},{"id":"ML-T00962","row_version":2,"title":"성별 표현의 변장","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00956","tag_path":[],"summary":"성별 표현의 변장은 인물이 옷차림·말투·외양을 바꾸어 타인에게 다른 성별로 인식되도록 꾸미는 행동이다. 성별 정체성이나 평소의 성별 표현 자체와 동일시하지 말고, 인물이 특정 상황에서 신분을 위장하려는 목적이 있는지 기준으로 삼는다.","accent":"#7B7594","tab":"#AF8665","facet":"인물","bookmark":"성별 표현의 변장","entry_url":"cards/ML-T00962/index.html"},{"id":"ML-T00963","row_version":2,"title":"변화 궤적","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"group","parent_id":"ML-F09","tag_path":[],"summary":"변화 궤적은 이야기의 시간 동안 인물의 가치관·행동·관계나 자기 이해가 어떻게 달라지는지를 가리킨다. 사건을 겪거나 나이가 드는 것만으로 변화라 하지 말고, 인물의 상태가 이전과 비교해 지속적으로 달라졌는지 본다.","accent":"#7B7594","tab":"#6D7BA1","facet":"인물","bookmark":"변화 궤적","entry_url":"cards/ML-T00963/index.html"},{"id":"ML-T00964","row_version":2,"title":"성장하는 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00963","tag_path":[],"summary":"성장하는 인물은 경험과 선택을 거치며 지식·역량·책임감이나 자기 이해를 넓혀 가는 인물이다. 단순히 강해지거나 성공하는 것과 구별해, 배움이 판단과 행동의 변화로 이어지는지 살핀다.","accent":"#7B7594","tab":"#6D7BA1","facet":"인물","bookmark":"성장하는 인물","entry_url":"cards/ML-T00964/index.html"},{"id":"ML-T00965","row_version":2,"title":"타락하는 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00963","tag_path":[],"summary":"타락하는 인물은 자신의 선택과 행동을 거치며 도덕적 기준이나 타인에 대한 태도가 이전보다 해로운 방향으로 무너지는 인물이다. 한 번의 잘못이나 외부에 의한 평판 악화와 구별해, 인물의 가치와 행위가 점진적으로 변하는지 본다.","accent":"#7B7594","tab":"#6D7BA1","facet":"인물","bookmark":"타락하는 인물","entry_url":"cards/ML-T00965/index.html"},{"id":"ML-T00966","row_version":2,"title":"회심하는 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00963","tag_path":[],"summary":"회심하는 인물은 신념이나 가치관을 크게 바꾸고 그 변화에 따라 새로운 방향의 행동을 선택하는 인물이다. 단순한 후회나 일시적인 편들기와 구별해, 전환이 인물의 지속적인 판단과 행동에 반영되는지 살핀다.","accent":"#7B7594","tab":"#6D7BA1","facet":"인물","bookmark":"회심하는 인물","entry_url":"cards/ML-T00966/index.html"},{"id":"ML-T00967","row_version":3,"title":"정체하는 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00963","tag_path":[],"summary":"정체하는 인물은 주요 사건과 시간이 지나도 핵심 가치관이나 행동 방식이 크게 바뀌지 않는 인물이다. 변화가 없다는 사실만으로 변화 궤적의 기능이 있다고 보지 말고, 그 일관성이 주변 인물이나 갈등과 어떤 관계를 맺는지 확인한다.","accent":"#7B7594","tab":"#6D7BA1","facet":"인물","bookmark":"정체하는 인물","entry_url":"cards/ML-T00967/index.html"},{"id":"ML-T00968","row_version":2,"title":"퇴행하는 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00963","tag_path":[],"summary":"퇴행하는 인물은 경험을 거치면서 판단력·자립성·대인 관계의 성숙도 등이 이전보다 낮아지는 인물이다. 단순한 패배나 일시적 실수와 구별해, 후퇴가 지속되거나 반복되며 인물의 선택 방식에 나타나는지 본다.","accent":"#7B7594","tab":"#6D7BA1","facet":"인물","bookmark":"퇴행하는 인물","entry_url":"cards/ML-T00968/index.html"},{"id":"ML-T00969","row_version":2,"title":"주변을 변화시키는 인물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":"tag","parent_id":"ML-T00963","tag_path":[],"summary":"주변을 변화시키는 인물은 자신의 행동이나 관계 맺기가 다른 인물들의 태도·선택·삶의 방향에 변화를 일으키는 인물이다. 영향력이 있다는 설명만으로 분류하지 말고, 주변 인물의 변화가 구체적으로 드러나며 그 변화가 해당 인물과 연결되는지 살핀다.","accent":"#7B7594","tab":"#6D7BA1","facet":"인물","bookmark":"주변을 변화시키는 인물","entry_url":"cards/ML-T00969/index.html"},{"id":"ML-T00970","row_version":2,"title":"가족·친족","original":"Family","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"group","parent_id":"ML-F10","tag_path":[],"summary":"가족·친족은 혈연, 혼인, 입양이나 사회적 인정으로 맺어져 지속되는 친족 관계를 가리킨다. 작품에서는 가족 구성원 사이의 유대와 의무가 관계의 중요한 축일 때 적용하고, 단순한 동거 집단은 구분한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"가족·친족","entry_url":"cards/ML-T00970/index.html"},{"id":"ML-T00971","row_version":2,"title":"부모와 자녀","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00970","tag_path":[],"summary":"부모와 자녀 관계는 양육과 보호의 책임, 세대 차이, 자녀의 성장이나 독립을 중심으로 형성된다. 작품에서 부모 역할과 자녀 역할의 상호작용이 핵심일 때 쓰며, 연령 차이만으로는 해당하지 않는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"부모와 자녀","entry_url":"cards/ML-T00971/index.html"},{"id":"ML-T00972","row_version":4,"title":"형제자매","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00970","tag_path":[],"summary":"형제자매 관계는 같은 부모나 양육 환경을 공유하며 맺는 수평적 가족 관계로, 친밀감과 경쟁이 함께 나타날 수 있다. 작품에서 형제자매로서의 유대나 역할이 서사에 영향을 줄 때 적용하고, 친구처럼 가까운 관계만으로는 분류하지 않는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"형제자매","entry_url":"cards/ML-T00972/index.html"},{"id":"ML-T00973","row_version":2,"title":"부부","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00970","tag_path":[],"summary":"부부 관계는 혼인으로 맺어진 두 사람의 공동생활과 그에 따른 정서적·사회적 책임을 포함한다. 작품에서 혼인 관계 자체가 갈등이나 선택의 중심일 때 적용하며, 연애 중인 사이는 구분한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"부부","entry_url":"cards/ML-T00973/index.html"},{"id":"ML-T00974","row_version":2,"title":"조손 관계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00970","tag_path":[],"summary":"조손 관계는 조부모와 손자녀 사이의 세대 간 유대로, 양육·전승·보살핌이나 세대 차이가 관계를 빚는다. 작품에서 이 세대적 위치가 상호작용에 중요할 때 쓰며, 나이 많은 보호자와 어린 인물의 관계만으로는 충분하지 않다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"조손 관계","entry_url":"cards/ML-T00974/index.html"},{"id":"ML-T00975","row_version":3,"title":"입양 가족","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00970","tag_path":[],"summary":"혈연 외의 관계를 통해 부모와 자녀가 되어 함께 살아가는 가족 구성을 찾는 태그다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"입양 가족","entry_url":"cards/ML-T00975/index.html"},{"id":"ML-T00976","row_version":2,"title":"의붓가족","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00970","tag_path":[],"summary":"의붓가족은 재혼이나 새 혼인으로 서로 가족이 된 구성원들이 함께 이루는 가족 관계다. 작품에서 새로 형성된 친족 역할이나 그 조정이 중요할 때 적용하며, 혈연이 없다는 사실만으로는 해당하지 않는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"의붓가족","entry_url":"cards/ML-T00976/index.html"},{"id":"ML-T00977","row_version":2,"title":"혈연을 모르는 가족","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00970","tag_path":[],"summary":"혈연을 모르는 가족은 구성원들이 친족이라는 사실을 알지 못하거나 관계의 진실이 감춰진 상태를 가리킨다. 작품에서 혈연의 미인지가 관계 형성과 선택에 실질적 영향을 줄 때 적용하고, 단순한 출생 비밀은 가족 관계가 드러나기 전까지 구분한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"혈연을 모르는 가족","entry_url":"cards/ML-T00977/index.html"},{"id":"ML-T00978","row_version":2,"title":"선택한 가족","original":"Family of Choice","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00970","tag_path":[],"summary":"혈연이나 법적 관계 밖의 사람들이 서로를 돌보고 책임지며 가족과 같은 유대를 만드는 관계 설정이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"선택한 가족","entry_url":"cards/ML-T00978/index.html"},{"id":"ML-T00979","row_version":2,"title":"연애 상태","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"group","parent_id":"ML-F10","tag_path":[],"summary":"연애 상태는 인물들이 서로를 사랑하거나 연애 대상으로 여기며 맺고 있는 관계의 현재 국면을 나타낸다. 작품에서 연애의 성립 여부나 상호성, 공개 여부가 구체적으로 중요할 때 적용하며, 막연한 호감만으로 상태를 단정하지 않는다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"연애 상태","entry_url":"cards/ML-T00979/index.html"},{"id":"ML-T00980","row_version":2,"title":"첫사랑","original":"First Love","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00979","tag_path":[],"summary":"인물이 처음 깊이 마음을 준 사람을 시간이 지난 뒤에도 특별하게 기억하고 새 관계와 비교하는 감정적 경험이다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"첫사랑","entry_url":"cards/ML-T00980/index.html"},{"id":"ML-T00981","row_version":2,"title":"짝사랑","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00979","tag_path":[],"summary":"짝사랑은 한 사람이 상대에게 연애 감정을 품지만 그 감정이 알려지지 않았거나 같은 방식으로 돌아오지 않는 상태다. 작품에서 감정의 비대칭이 선택이나 긴장을 이끌 때 쓰며, 고백 전이라는 이유만으로 상대의 마음까지 짝사랑이라고 단정하지 않는다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"짝사랑","entry_url":"cards/ML-T00981/index.html"},{"id":"ML-T00982","row_version":2,"title":"상호 연애","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00979","tag_path":[],"summary":"상호 연애는 두 사람이 서로의 연애 감정을 알고 받아들여 연인으로 관계를 맺은 상태다. 작품에서 양쪽의 감정과 관계 성립이 확인될 때 적용하며, 한쪽의 추측이나 일방적 구애는 구분한다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"상호 연애","entry_url":"cards/ML-T00982/index.html"},{"id":"ML-T00983","row_version":2,"title":"비밀 연애","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00979","tag_path":[],"summary":"비밀 연애는 연인 관계를 맺은 당사자들이 주변 사람에게 그 사실을 감추는 상태다. 작품에서 비공개가 관계 유지나 갈등의 조건일 때 적용하며, 아직 연인이 되지 않은 짝사랑이나 사적인 데이트만으로는 해당하지 않는다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"비밀 연애","entry_url":"cards/ML-T00983/index.html"},{"id":"ML-T00984","row_version":2,"title":"금지된 사랑","original":"Forbidden Love","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00979","tag_path":[],"summary":"사회 규범이나 집단의 금기가 두 사람의 연애를 가로막아 관계를 숨기거나 공개적으로 이어 가기 어렵게 만든다. 편견에서 비롯한 금지와 동의·권력 차이 때문에 필요한 보호 목적의 제한은 구분해 다룬다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"금지된 사랑","entry_url":"cards/ML-T00984/index.html"},{"id":"ML-T00985","row_version":2,"title":"삼각관계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00979","tag_path":[],"summary":"삼각관계는 세 인물 사이의 연애 감정이나 선택이 서로 얽혀 긴장을 만드는 관계 구조다. 작품에서 세 사람의 감정 연결이 핵심일 때 적용하며, 단순히 두 사람이 한 사람을 좋아하는 구도와 실제 관계망을 구별한다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"삼각관계","entry_url":"cards/ML-T00985/index.html"},{"id":"ML-T00986","row_version":3,"title":"다자 연애","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00979","tag_path":[],"summary":"다자 연애는 세 명 이상이 합의와 인지를 바탕으로 연애 관계에 참여하는 형태다. 작품에서 복수의 연인이 관계의 당사자로 인정될 때 적용하며, 질투를 낳는 경쟁자나 삼각관계와는 상호 합의 여부로 구별한다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"다자 연애","entry_url":"cards/ML-T00986/index.html"},{"id":"ML-T00987","row_version":2,"title":"재회 연애","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00979","tag_path":[],"summary":"재회 연애는 과거 연인이 헤어졌다가 다시 연애 관계를 맺는 흐름이다. 작품에서 이전 관계의 이력과 재결합이 중요할 때 적용하며, 오랜 친구가 새로 사랑에 빠지는 경우와 구분한다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"재회 연애","entry_url":"cards/ML-T00987/index.html"},{"id":"ML-T00988","row_version":2,"title":"관계 출발","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"group","parent_id":"ML-F10","tag_path":[],"summary":"관계 출발은 인물 사이의 지속적인 관계가 처음 성립하거나 새로운 형태로 전환되는 계기와 조건을 가리킨다. 작품에서 만남이나 계약, 공동 상황이 이후 관계의 틀을 정할 때 적용하며, 이미 형성된 관계의 단순한 변화는 구분한다.","accent":"#9D7C82","tab":"#8B739C","facet":"관계","bookmark":"관계 출발","entry_url":"cards/ML-T00988/index.html"},{"id":"ML-T00989","row_version":1,"title":"계약 결혼 관계","original":"","aliases":["계약결혼","계약 결혼"],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00988","tag_path":[],"summary":"감정 외의 목적이나 조건을 정한 합의로 맺는 혼인 관계다. 합의의 조건과 실제 관계의 변화 사이에서 이야기가 전개된다.","accent":"#9D7C82","tab":"#8B739C","facet":"관계","bookmark":"계약 결혼 관계","entry_url":"cards/ML-T00989/index.html"},{"id":"ML-T00990","row_version":2,"title":"정략결혼 관계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00988","tag_path":[],"summary":"정략결혼 관계는 개인의 애정보다 가문·권력·재산 등 외부 이해를 위해 혼인으로 맺어진 관계다. 작품에서 혼인의 정치적·사회적 목적이 관계의 조건을 정할 때 적용하며, 당사자들이 연애 끝에 결혼하는 경우와 구별한다.","accent":"#9D7C82","tab":"#8B739C","facet":"관계","bookmark":"정략결혼 관계","entry_url":"cards/ML-T00990/index.html"},{"id":"ML-T00991","row_version":3,"title":"가짜 연인","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00988","tag_path":[],"summary":"가짜 연인은 실제 연애 감정이나 합의된 연인 관계 없이 연인인 것처럼 행동하는 두 사람을 가리킨다. 작품에서 연인 행세가 외부를 속이거나 당사자 사이의 관계를 바꾸는 장치일 때 적용하며, 비밀 연애처럼 실제 연인인 경우와 구분한다.","accent":"#9D7C82","tab":"#8B739C","facet":"관계","bookmark":"가짜 연인","entry_url":"cards/ML-T00991/index.html"},{"id":"ML-T00992","row_version":2,"title":"동거 관계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00988","tag_path":[],"summary":"동거 관계는 혼인 여부와 무관하게 둘 이상의 인물이 한 공간에서 생활을 함께하며 형성하는 관계다. 작품에서 공동생활이 친밀감이나 갈등의 조건이 될 때 적용하며, 잠시 같은 장소에 머무는 동행과 구별한다.","accent":"#9D7C82","tab":"#8B739C","facet":"관계","bookmark":"동거 관계","entry_url":"cards/ML-T00992/index.html"},{"id":"ML-T00993","row_version":2,"title":"소꿉친구","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00988","tag_path":[],"summary":"소꿉친구는 어린 시절부터 알고 지내며 오랜 공동 경험을 쌓은 친구 관계다. 작품에서 유년기부터 이어진 친분이 현재 관계에 영향을 줄 때 적용하며, 성인이 된 뒤 오래 사귄 친구와는 시작 시점을 구별한다.","accent":"#9D7C82","tab":"#8B739C","facet":"관계","bookmark":"소꿉친구","entry_url":"cards/ML-T00993/index.html"},{"id":"ML-T00994","row_version":2,"title":"낯선 동행","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00988","tag_path":[],"summary":"낯선 동행은 서로 잘 모르던 인물들이 공동 목적이나 상황 때문에 함께 움직이기 시작한 관계다. 작품에서 동행 과정에서 신뢰와 역할이 형성될 때 적용하며, 이미 친분이 있던 일행의 여행에는 쓰지 않는다.","accent":"#9D7C82","tab":"#8B739C","facet":"관계","bookmark":"낯선 동행","entry_url":"cards/ML-T00994/index.html"},{"id":"ML-T00995","row_version":2,"title":"원수와의 동맹","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00988","tag_path":[],"summary":"원수와의 동맹은 적대하던 상대들이 더 큰 위협이나 공동 목표에 대응하려고 협력하는 관계다. 작품에서 과거의 적대와 현재의 협력이 동시에 긴장을 만들 때 적용하며, 본래부터 우호적인 동료와 구별한다.","accent":"#9D7C82","tab":"#8B739C","facet":"관계","bookmark":"원수와의 동맹","entry_url":"cards/ML-T00995/index.html"},{"id":"ML-T00996","row_version":2,"title":"우정·동료","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"group","parent_id":"ML-F10","tag_path":[],"summary":"서로를 친구나 동료로 받아들이고 신뢰를 쌓는 관계를 찾는 태그다.","accent":"#9D7C82","tab":"#A58A4E","facet":"관계","bookmark":"우정·동료","entry_url":"cards/ML-T00996/index.html"},{"id":"ML-T00997","row_version":3,"title":"절친","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00996","tag_path":[],"summary":"절친은 서로 깊은 신뢰와 친밀감을 나누며 사적인 면까지 의지하는 가까운 친구다. 작품에서 우정의 깊이가 선택이나 감정에 실질적으로 작용할 때 적용하며, 함께 일하는 것만으로는 절친이라 할 수 없다.","accent":"#9D7C82","tab":"#A58A4E","facet":"관계","bookmark":"절친","entry_url":"cards/ML-T00997/index.html"},{"id":"ML-T00998","row_version":2,"title":"동료애","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00996","tag_path":[],"summary":"동료애는 같은 일이나 목표를 함께 수행하는 사람들 사이에 쌓이는 연대감과 상호 신뢰다. 작품에서 공동 활동을 통해 형성된 유대가 중요할 때 적용하며, 사적 친분만 중심인 우정과 구별한다.","accent":"#9D7C82","tab":"#A58A4E","facet":"관계","bookmark":"동료애","entry_url":"cards/ML-T00998/index.html"},{"id":"ML-T00999","row_version":3,"title":"전우","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00996","tag_path":[],"summary":"전우 관계는 전쟁이나 무장 충돌을 함께 겪으며 생긴 동료 사이의 유대다. 작품에서 전투의 공동 경험과 위험 분담이 관계를 규정할 때 적용하며, 일반적인 직장·팀 동료 관계와 구별한다.","accent":"#9D7C82","tab":"#A58A4E","facet":"관계","bookmark":"전우","entry_url":"cards/ML-T00999/index.html"},{"id":"ML-T01000","row_version":2,"title":"파트너","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00996","tag_path":[],"summary":"파트너는 특정 임무나 활동에서 서로 보완하며 책임을 나누는 두 인물의 협력 관계다. 작품에서 역할 분담과 상호 신뢰가 관계의 핵심일 때 적용하며, 단순히 같은 팀에 속한 구성원과 구분한다.","accent":"#9D7C82","tab":"#A58A4E","facet":"관계","bookmark":"파트너","entry_url":"cards/ML-T01000/index.html"},{"id":"ML-T01001","row_version":2,"title":"버디 관계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00996","tag_path":[],"summary":"버디 관계는 두 인물이 짝을 이루어 함께 움직이며 서로의 차이와 호흡을 드러내는 동행 구조다. 작품에서 둘의 공동 활동과 상호작용이 중심일 때 적용하며, 꼭 절친이거나 능력이 대등해야 하는 것은 아니다.","accent":"#9D7C82","tab":"#A58A4E","facet":"관계","bookmark":"버디 관계","entry_url":"cards/ML-T01001/index.html"},{"id":"ML-T01002","row_version":2,"title":"팀 동료","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00996","tag_path":[],"summary":"팀 동료는 공동 목표를 위해 하나의 팀에 속해 역할을 나누는 구성원들 사이의 관계다. 작품에서 팀 내 협력과 역할 조정이 중요할 때 적용하며, 특정 두 사람의 일대일 파트너십과는 범위를 구별한다.","accent":"#9D7C82","tab":"#A58A4E","facet":"관계","bookmark":"팀 동료","entry_url":"cards/ML-T01002/index.html"},{"id":"ML-T01003","row_version":3,"title":"경쟁적 우정","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T00996","tag_path":[],"summary":"경쟁적 우정은 친밀한 친구들이 서로를 경쟁 상대로 삼아 겨루면서도 관계를 유지하는 형태다. 작품에서 경쟁이 우정을 자극하거나 시험할 때 적용하며, 적대감만 있고 우정의 기반이 없는 라이벌 관계와 구분한다.","accent":"#9D7C82","tab":"#A58A4E","facet":"관계","bookmark":"경쟁적 우정","entry_url":"cards/ML-T01003/index.html"},{"id":"ML-T01004","row_version":2,"title":"위계·교육","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"group","parent_id":"ML-F10","tag_path":[],"summary":"위계·교육 관계는 지식이나 권한, 지위의 차이에 따라 한쪽이 가르치거나 지휘하고 다른 쪽이 배우거나 따르는 구조다. 작품에서 비대칭적 권한과 학습·복종의 역할이 관계를 규정할 때 적용하며, 단순한 나이 차이나 경험 차이는 구분한다.","accent":"#9D7C82","tab":"#528982","facet":"관계","bookmark":"위계·교육","entry_url":"cards/ML-T01004/index.html"},{"id":"ML-T01005","row_version":2,"title":"스승과 제자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01004","tag_path":[],"summary":"스승과 제자는 한 인물이 지식·기술·가르침을 전하고 다른 인물이 이를 배우며 맺는 교육 관계다. 작품에서 가르침과 전승, 제자의 성장이나 독립이 관계의 핵심일 때 적용하며, 공식 교사와 학생 역할만으로 한정하지 않는다.","accent":"#9D7C82","tab":"#528982","facet":"관계","bookmark":"스승과 제자","entry_url":"cards/ML-T01005/index.html"},{"id":"ML-T01006","row_version":2,"title":"군주와 신하","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01004","tag_path":[],"summary":"군주와 신하는 통치권을 가진 군주와 그에게 충성·복무하는 신하 사이의 정치적 위계 관계다. 작품에서 통치 권한과 충성 의무가 관계를 움직일 때 적용하며, 일반적인 고용주와 직원 관계와 구별한다.","accent":"#9D7C82","tab":"#528982","facet":"관계","bookmark":"군주와 신하","entry_url":"cards/ML-T01006/index.html"},{"id":"ML-T01007","row_version":2,"title":"주인과 종속자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01004","tag_path":[],"summary":"주인과 종속자는 소유권이나 강한 권력 차이로 한쪽이 다른 쪽의 행동과 처지를 통제하는 관계다. 작품에서 종속이 제도적·실질적 강제로 작동할 때 적용하며, 자발적으로 따르는 제자나 부하와 구별한다.","accent":"#9D7C82","tab":"#528982","facet":"관계","bookmark":"주인과 종속자","entry_url":"cards/ML-T01007/index.html"},{"id":"ML-T01008","row_version":2,"title":"상사와 부하","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01004","tag_path":[],"summary":"상사와 부하는 조직 안에서 한쪽이 업무를 지시·평가하고 다른 쪽이 이를 수행하는 직무상 위계 관계다. 작품에서 조직의 권한과 업무 책임이 상호작용의 기준일 때 적용하며, 사적 지배나 군주제의 충성 관계와 구분한다.","accent":"#9D7C82","tab":"#528982","facet":"관계","bookmark":"상사와 부하","entry_url":"cards/ML-T01008/index.html"},{"id":"ML-T01009","row_version":3,"title":"선배와 후배","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01004","tag_path":[],"summary":"선배와 후배는 같은 학교·조직·활동 공동체에서 먼저 들어온 사람과 나중에 들어온 사람 사이의 선후 기수 관계다. 작품에서 기수 차이가 예우나 지도, 갈등을 낳을 때 적용하며, 직급이 다른 직장 동료 관계와는 기준을 구별한다.","accent":"#9D7C82","tab":"#528982","facet":"관계","bookmark":"선배와 후배","entry_url":"cards/ML-T01009/index.html"},{"id":"ML-T01010","row_version":2,"title":"후원자와 수혜자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01004","tag_path":[],"summary":"후원자와 수혜자는 한쪽이 자원·기회·보호를 제공하고 다른 쪽이 그 지원을 받는 관계다. 작품에서 지원의 조건이나 그에 따른 영향력이 중요할 때 적용하며, 상호 교환이나 단순한 친절만으로는 구분한다.","accent":"#9D7C82","tab":"#528982","facet":"관계","bookmark":"후원자와 수혜자","entry_url":"cards/ML-T01010/index.html"},{"id":"ML-T01011","row_version":2,"title":"보호·의존","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"group","parent_id":"ML-F10","tag_path":[],"summary":"보호·의존은 한 인물이 안전이나 생존을 위해 다른 인물에게 기대고, 상대가 보호 역할을 맡는 관계 양상이다. 작품에서 보호 능력과 의존이 관계의 균형을 좌우할 때 적용하며, 일시적 도움만으로 지속적 의존을 가정하지 않는다.","accent":"#9D7C82","tab":"#7D8FA3","facet":"관계","bookmark":"보호·의존","entry_url":"cards/ML-T01011/index.html"},{"id":"ML-T01012","row_version":2,"title":"보호자와 피보호자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01011","tag_path":[],"summary":"보호자와 피보호자는 한쪽이 위험을 막고 생활을 책임지며 다른 쪽이 그 보호를 받는 역할 관계다. 작품에서 보호 책임과 피보호자의 안전·자율성 문제가 중요할 때 적용하며, 잠깐 구해 준 인물과 구별한다.","accent":"#9D7C82","tab":"#7D8FA3","facet":"관계","bookmark":"보호자와 피보호자","entry_url":"cards/ML-T01012/index.html"},{"id":"ML-T01013","row_version":2,"title":"구원자와 피구원자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01011","tag_path":[],"summary":"구원자와 피구원자는 위기에서 한쪽이 다른 쪽을 결정적으로 구해 주며 생기는 관계다. 작품에서 구출 경험이 두 인물의 유대나 빚, 권력 차이를 형성할 때 적용하며, 평상시 보호자 역할과는 위기의 구출을 기준으로 구별한다.","accent":"#9D7C82","tab":"#7D8FA3","facet":"관계","bookmark":"구원자와 피구원자","entry_url":"cards/ML-T01013/index.html"},{"id":"ML-T01014","row_version":2,"title":"상호 의존","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01011","tag_path":[],"summary":"상호 의존은 두 인물이 각자 상대의 도움이나 기능에 기대며 양쪽 모두 관계에서 필요한 것을 얻는 상태다. 작품에서 의존이 양방향으로 확인될 때 적용하며, 한쪽만 지속적으로 매달리는 관계와 구분한다.","accent":"#9D7C82","tab":"#7D8FA3","facet":"관계","bookmark":"상호 의존","entry_url":"cards/ML-T01014/index.html"},{"id":"ML-T01015","row_version":2,"title":"일방적 의존","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01011","tag_path":[],"summary":"일방적 의존은 한 인물이 상대에게 정서적·물질적으로 크게 기대지만 그 기대가 대등하게 돌아오지 않는 상태다. 작품에서 의존의 방향이 한쪽으로 치우친 것이 중요할 때 적용하며, 상호 도움이나 단순한 호감과 구별한다.","accent":"#9D7C82","tab":"#7D8FA3","facet":"관계","bookmark":"일방적 의존","entry_url":"cards/ML-T01015/index.html"},{"id":"ML-T01016","row_version":2,"title":"돌봄 관계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01011","tag_path":[],"summary":"돌봄 관계는 한 인물이 다른 인물의 신체적·정서적 필요를 지속적으로 살피고 지원하는 관계다. 작품에서 일상적인 보살핌과 책임의 분담이 관계를 규정할 때 적용하며, 위기 때 한 번 돕는 행동과 구분한다.","accent":"#9D7C82","tab":"#7D8FA3","facet":"관계","bookmark":"돌봄 관계","entry_url":"cards/ML-T01016/index.html"},{"id":"ML-T01017","row_version":3,"title":"공생 관계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01011","tag_path":[],"summary":"공생 관계는 서로 다른 인물들이 함께 있을 때 각자의 생존이나 목표 달성에 이익을 얻는 결합이다. 작품에서 양쪽의 지속적인 상호 이익이 드러날 때 적용하며, 한쪽만 이득을 얻는 착취 관계와 구별한다.","accent":"#9D7C82","tab":"#7D8FA3","facet":"관계","bookmark":"공생 관계","entry_url":"cards/ML-T01017/index.html"},{"id":"ML-T01018","row_version":2,"title":"착취 관계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01011","tag_path":[],"summary":"착취 관계는 한쪽이 상대의 노동·자원·취약성을 이용해 이익을 얻고 부담이나 피해를 상대에게 떠넘기는 구조다. 작품에서 이익과 비용의 불균형이 반복되거나 강요될 때 적용하며, 합의된 상호 협력과 구별한다.","accent":"#9D7C82","tab":"#7D8FA3","facet":"관계","bookmark":"착취 관계","entry_url":"cards/ML-T01018/index.html"},{"id":"ML-T01019","row_version":2,"title":"적대·경쟁","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"group","parent_id":"ML-F10","tag_path":[],"summary":"적대·경쟁은 인물들이 서로의 목표를 방해하거나 우위와 성과를 두고 겨루는 관계 양상이다. 작품에서 대립의 지속이나 경쟁 규칙이 관계를 형성할 때 적용하며, 일회성 의견 충돌만으로는 분류하지 않는다.","accent":"#9D7C82","tab":"#A07A87","facet":"관계","bookmark":"적대·경쟁","entry_url":"cards/ML-T01019/index.html"},{"id":"ML-T01020","row_version":5,"title":"숙적","original":"Arch-Enemy","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01019","tag_path":[],"summary":"여러 적 가운데 주인공과 가장 깊은 원한이나 대조를 이루는 상대. 단순히 강한 적이 아니라 반복된 대결이 서로의 정체성을 규정한다. 가족인 적이 반복해서 나타나는 아버지가 가장 큰 적이 되기는 한 변형이다.","accent":"#9D7C82","tab":"#A07A87","facet":"관계","bookmark":"숙적","entry_url":"cards/ML-T01020/index.html"},{"id":"ML-T01021","row_version":3,"title":"라이벌","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01019","tag_path":[],"summary":"라이벌은 비슷한 목표나 분야에서 서로를 의식하며 우위나 성취를 겨루는 상대다. 작품에서 반복되는 경쟁이 각자의 행동이나 성장을 자극할 때 적용하며, 목표가 겹치지 않는 적대자와 구별한다.","accent":"#9D7C82","tab":"#A07A87","facet":"관계","bookmark":"라이벌","entry_url":"cards/ML-T01021/index.html"},{"id":"ML-T01022","row_version":2,"title":"복수 관계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01019","tag_path":[],"summary":"복수 관계는 피해를 입었다고 여기는 인물이 가해자로 지목한 상대에게 응징을 추구하며 형성되는 대립이다. 작품에서 과거의 피해와 보복 의지가 현재 관계를 이끌 때 적용하며, 동기가 복수와 무관한 적대는 구분한다.","accent":"#9D7C82","tab":"#A07A87","facet":"관계","bookmark":"복수 관계","entry_url":"cards/ML-T01022/index.html"},{"id":"ML-T01023","row_version":2,"title":"추적자와 도망자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01019","tag_path":[],"summary":"추적자와 도망자는 한쪽이 상대를 찾아 붙잡으려 하고 다른 쪽이 추적을 피하는 대립 관계다. 작품에서 추적과 회피가 반복되는 행동 구조의 중심일 때 적용하며, 단순한 추격 장면이나 상호 추적은 구별한다.","accent":"#9D7C82","tab":"#A07A87","facet":"관계","bookmark":"추적자와 도망자","entry_url":"cards/ML-T01023/index.html"},{"id":"ML-T01024","row_version":2,"title":"가해자와 피해자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01019","tag_path":[],"summary":"가해자와 피해자는 한쪽의 행동으로 다른 쪽이 신체적·정서적·사회적 피해를 입은 관계다. 작품에서 가해 행위와 피해의 결과가 인물 사이의 구조를 규정할 때 적용하며, 대등한 경쟁이나 우발적 갈등과 구분한다.","accent":"#9D7C82","tab":"#A07A87","facet":"관계","bookmark":"가해자와 피해자","entry_url":"cards/ML-T01024/index.html"},{"id":"ML-T01025","row_version":2,"title":"배신자와 피배신자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01019","tag_path":[],"summary":"배신자와 피배신자는 신뢰나 약속을 저버린 인물과 그 배신으로 피해를 입은 인물 사이의 관계다. 작품에서 기존 신뢰와 그것의 파기가 현재 대립을 만드는 경우에 적용하며, 처음부터 적대했던 상대와 구별한다.","accent":"#9D7C82","tab":"#A07A87","facet":"관계","bookmark":"배신자와 피배신자","entry_url":"cards/ML-T01025/index.html"},{"id":"ML-T01026","row_version":3,"title":"관계 변화 양상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"group","parent_id":"ML-F10","tag_path":[],"summary":"관계 변화 양상은 인물 사이의 관계가 만남·갈등·화해·단절 등을 거쳐 다른 상태로 이동하는 흐름이다. 작품에서 변화의 단계나 계기가 관계 서사의 핵심일 때 적용하며, 특정한 관계 유형 자체를 가리키는 항목과 구분한다.","accent":"#9D7C82","tab":"#79866C","facet":"관계","bookmark":"관계 변화 양상","entry_url":"cards/ML-T01026/index.html"},{"id":"ML-T01027","row_version":3,"title":"적에서 동료로","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01026","tag_path":[],"summary":"서로 적대하던 인물들이 갈등을 거쳐 공동 목표를 위해 협력하는 관계로 바뀐다. 일시적인 휴전이나 이해관계의 일치만으로 끝나지 않고, 이후 동료로 기능하는 변화가 서사에 드러날 때 적용한다.","accent":"#9D7C82","tab":"#79866C","facet":"관계","bookmark":"적에서 동료로","entry_url":"cards/ML-T01027/index.html"},{"id":"ML-T01028","row_version":3,"title":"적에서 연인으로","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01026","tag_path":[],"summary":"대립하던 인물들 사이에 적대감이 친밀감과 연애 감정으로 바뀌며 연인 관계가 형성된다. 한쪽의 일방적인 호감이나 적대 관계를 유지한 채 벌어지는 유혹만으로는 부족하고, 상호적인 연애 관계의 성립이 확인될 때 적용한다.","accent":"#9D7C82","tab":"#79866C","facet":"관계","bookmark":"적에서 연인으로","entry_url":"cards/ML-T01028/index.html"},{"id":"ML-T01029","row_version":3,"title":"친구에서 연인으로","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01026","tag_path":[],"summary":"친구로 지내던 두 인물이 우정에서 연애 감정으로 나아가 연인이 된다. 기존의 친밀함이 유지되더라도 관계의 성격이 연애로 바뀌어야 하며, 친구 사이의 짝사랑만 묘사될 때는 적용하지 않는다.","accent":"#9D7C82","tab":"#79866C","facet":"관계","bookmark":"친구에서 연인으로","entry_url":"cards/ML-T01029/index.html"},{"id":"ML-T01030","row_version":2,"title":"동료에서 적으로","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01026","tag_path":[],"summary":"함께 일하거나 싸우던 동료들이 갈등이나 이해관계의 충돌로 적대 관계에 들어선다. 의견 차이나 경쟁이 있어도 협력 관계가 유지된다면 해당하지 않으며, 동료로서의 유대가 적대감으로 대체되는 변화가 있어야 한다.","accent":"#9D7C82","tab":"#79866C","facet":"관계","bookmark":"동료에서 적으로","entry_url":"cards/ML-T01030/index.html"},{"id":"ML-T01031","row_version":2,"title":"신뢰 붕괴","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01026","tag_path":[],"summary":"관계를 지탱하던 믿음이 배신, 기만, 반복된 실망 등으로 무너져 상대를 믿기 어려워지는 과정이나 상태다. 단순한 오해나 일시적인 의심과 구별해, 신뢰의 손상으로 관계의 행동이나 선택이 달라질 때 적용한다.","accent":"#9D7C82","tab":"#79866C","facet":"관계","bookmark":"신뢰 붕괴","entry_url":"cards/ML-T01031/index.html"},{"id":"ML-T01032","row_version":2,"title":"관계 회복","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01026","tag_path":[],"summary":"갈등이나 단절로 손상된 관계가 대화, 책임 인정, 행동의 변화 등을 거쳐 다시 이어지는 과정이다. 사건이 끝나거나 인물들이 같은 편에 서는 것만으로는 부족하고, 이전 관계의 균열을 다루고 유대를 회복해야 한다.","accent":"#9D7C82","tab":"#79866C","facet":"관계","bookmark":"관계 회복","entry_url":"cards/ML-T01032/index.html"},{"id":"ML-T01033","row_version":2,"title":"위계 역전","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01026","tag_path":[],"summary":"관계에서 결정권이나 영향력을 행사하던 쪽이 바뀌어 기존의 위아래가 뒤집힌다. 단순한 전투력 우세나 직책 변경과 구별해, 두 인물 사이의 실제 발언권·의존도·통제력이 역전될 때 적용한다.","accent":"#9D7C82","tab":"#79866C","facet":"관계","bookmark":"위계 역전","entry_url":"cards/ML-T01033/index.html"},{"id":"ML-T01034","row_version":2,"title":"집단 구성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"group","parent_id":"ML-F10","tag_path":[],"summary":"여러 인물이 어떤 목적이나 상황을 중심으로 한 집단을 이루고, 구성원 사이의 역할과 관계가 형성되는 방식이다. 인물들이 같은 장소에 있거나 잠시 협력하는 것만으로는 집단이 성립하지 않으며, 반복되는 공동 활동이나 집단 내 관계가 드러나야 한다.","accent":"#9D7C82","tab":"#AF8665","facet":"관계","bookmark":"집단 구성","entry_url":"cards/ML-T01034/index.html"},{"id":"ML-T01035","row_version":2,"title":"이인조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01034","tag_path":[],"summary":"두 인물이 한 쌍을 이루어 사건을 함께 수행하고 서로의 역할이나 성격이 맞물리는 구성이다. 단순히 장면마다 두 사람만 등장하는 경우와 구별해, 둘의 협력이나 대비가 작품의 지속적인 관계 구조로 기능해야 한다.","accent":"#9D7C82","tab":"#AF8665","facet":"관계","bookmark":"이인조","entry_url":"cards/ML-T01035/index.html"},{"id":"ML-T01036","row_version":2,"title":"삼인조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01034","tag_path":[],"summary":"세 인물이 하나의 단위로 움직이며 각자의 역할과 상호 관계를 이루는 구성이다. 주요 인물이 셋이라는 사실만으로는 충분하지 않고, 세 사람 사이의 협력·대립·균형이 지속적으로 작동해야 한다.","accent":"#9D7C82","tab":"#AF8665","facet":"관계","bookmark":"삼인조","entry_url":"cards/ML-T01036/index.html"},{"id":"ML-T01037","row_version":2,"title":"사인조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01034","tag_path":[],"summary":"네 인물이 한 팀이나 단위로 함께 움직이며 구성원 간 역할과 상호작용을 형성한다. 작품의 인물 수가 우연히 넷인 경우와 구별해, 네 사람의 조합이 집단 활동이나 관계의 구조로 기능할 때 적용한다.","accent":"#9D7C82","tab":"#AF8665","facet":"관계","bookmark":"사인조","entry_url":"cards/ML-T01037/index.html"},{"id":"ML-T01038","row_version":3,"title":"다섯 명의 팀","original":"Five-Man Band","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":"tag","parent_id":"ML-T01034","tag_path":[],"summary":"중심 인물과 그를 보완하는 서로 다른 역할의 동료들로 이루어진 다섯 명 안팎의 모험 집단이다. 역할이 나뉜 팀의 친밀함은 구성원 모두가 참여하는 팀원들이 함께 연주하는 공연으로도 표현된다.","accent":"#9D7C82","tab":"#AF8665","facet":"관계","bookmark":"다섯 명의 팀","entry_url":"cards/ML-T01038/index.html"}]}.cards;